using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval — returns JsonTypeInfo<T> directly.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// Round-trip using the typed info to prove it works.
var json = JsonSerializer.Serialize(new Person("Ada", 37), personInfo);
Console.WriteLine($"Serialized: {json}");

Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {deserialized}");

// 2) Probe without throwing — TryGetTypeInfo returns false when metadata
//    isn't available instead of throwing InvalidOperationException.
//    Use an options instance with NO resolver to simulate "not available".
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = null
};

bool found = emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed);
Console.WriteLine($"\nTryGetTypeInfo on empty resolver => found: {found}, info: {probed?.Type.Name ?? "(null)"}");

// And confirm it succeeds on the fully-configured options.
bool found2 = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed2);
Console.WriteLine($"TryGetTypeInfo on configured resolver => found: {found2}, info: {probed2?.Type.Name ?? "(null)"}");

public record Person(string Name, int Age);

